# Generated by noon shell init. Source manually; no startup files are modified.
_noon_saved_status=$?
_noon_install() {
    local saved=$1
    autoload -Uz compinit add-zsh-hook
    (( $+functions[compdef] )) || compinit -i -D
    _noon_complete() {
        setopt local_options extended_glob
        local -a candidates
        local line path_mode
        path_mode=
        candidates=()
        while IFS= read -r line; do
            case $line in
                __NOON_COMPLETE_PATH_FILE__) path_mode=file ;;
                __NOON_COMPLETE_PATH_DIR__) path_mode=dir ;;
                *) candidates+=("$line") ;;
            esac
        done < <(command noon "${(@Q)words[@]:1:$((CURRENT-1))}" --generate-shell-completion 2>/dev/null)
        if [[ -n $path_mode ]]; then
            [[ ${words[CURRENT]} == -*=* ]] && compset -P '[^=]#='
            if [[ $path_mode == dir ]]; then
                _files -/
            else
                _files
            fi
            (( ${#candidates} )) && compadd -- "${candidates[@]}"
        elif (( ${#candidates} )); then
            [[ ${words[CURRENT]} == -*=* ]] && compset -P '[^=]#='
            compadd -- "${candidates[@]}"
        fi
        return 0
    }
    compdef _noon_complete noon
    add-zsh-hook -d chpwd _noon_chpwd
    _noon_job='@JOB@'
    if [[ -n $_noon_job ]]; then
        _noon_directory=$PWD
        _noon_project=$(command noon shell entry --record -- zsh "$_noon_job" '' "$PWD" "$PWD")
        _noon_chpwd() {
            local saved=$?
            _noon_project=$(command noon shell entry -- zsh "$_noon_job" "$_noon_project" "$_noon_directory" "$PWD")
            _noon_directory=$PWD
            return "$saved"
        }
        add-zsh-hook chpwd _noon_chpwd
    fi
    return "$saved"
}
_noon_install "$_noon_saved_status"
